const MODEL = 'gpt-4o-mini';
const b = $json.body || {};
if (!b.job || !b.profile) throw new Error('Need { job, profile, questions }');
const pasted = Array.isArray(b.questions) ? b.questions.filter(q=>q && q.question && q.question.trim()) : [];

// Read the live posting for richer, company-specific context (best-effort).
let fullPosting = b.job.description || '';
if (b.job.url) {
  try {
    const html = await this.helpers.httpRequest({ url:b.job.url, headers:{'User-Agent':'Mozilla/5.0 InternScout'}, timeout:20000 });
    const text = String(html).replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<[^>]+>/g,' ').replace(/&[a-z]+;/gi,' ').replace(/\s+/g,' ').trim();
    if (text.length > fullPosting.length) fullPosting = text.slice(0, 7000);
  } catch(e){}
}

const sys = 'You help a candidate apply to a remote internship. For EVERY question, produce 3-4 strong answer options, each from a DIFFERENT angle (e.g. project/achievement-led, skills-led, motivation-&-company-fit-led, concise/punchy). Ground every answer ONLY in the candidate resume, profile and their draft notes. NEVER invent experience, tools, employers, or credentials. Respect any word limit in the question. If the candidate provided no questions, PREDICT the 5-6 most likely application questions for this role and company (e.g. why this company, why you, a relevant project, biggest challenge solved, availability/timezone, what you want to learn) and answer those. Respond ONLY with JSON: {"questions":[{"question":string,"predicted":boolean,"options":[{"angle":string,"text":string}]}],"submission_checklist":[strings],"email_subject":string,"email_body":string,"honesty_check":string}.';

const user = 'ROLE\nTitle: '+b.job.title+'\nCompany: '+b.job.company+'\nLocation: '+(b.job.location||'')+'\n\nPOSTING (full text where available):\n'+fullPosting.slice(0,7000)+'\n\nCANDIDATE\nName: '+(b.profile.name||'')+'\nEmail: '+(b.profile.email||'')+'\nLinks: '+(b.profile.links||'')+'\nSkills: '+(b.profile.skills||'')+'\nInterests: '+(b.profile.interests||'')+'\n\nRESUME (source of truth):\n'+(b.tailored_resume||b.profile.resume||'')+'\n\n'+(pasted.length ? ('THE EXACT QUESTIONS TO ANSWER (with any draft notes):\n'+JSON.stringify(pasted,null,2)) : 'No questions provided — predict the most likely ones and answer them.');

return { json: { jobId:b.job.id, requestBody: { model:MODEL, temperature:0.45, response_format:{type:'json_object'}, messages:[{role:'system',content:sys},{role:'user',content:user}] } } };

const src = $('Build options request').item.json;
const raw = $json.choices?.[0]?.message?.content || '{}';
let out;
try { out = JSON.parse(raw.replace(/^```(json)?/m,'').replace(/```\s*$/m,'').trim()); }
catch(e){ out = { questions:[], submission_checklist:['Could not parse model output.'], email_subject:'', email_body:'' }; }
const questions = (out.questions||[]).map(q => ({
  question: q.question || '',
  predicted: !!q.predicted,
  options: Array.isArray(q.options) ? q.options.filter(o=>o&&o.text).slice(0,4) : [],
  selected: 0,
  answer: (q.options && q.options[0] && q.options[0].text) || ''
}));
return { json: { ok:true, jobId:src.jobId, questions, submission_checklist:out.submission_checklist||[], email_subject:out.email_subject||'', email_body:out.email_body||'', honesty_check:out.honesty_check||'', preparedAt:new Date().toISOString() } };
